<?php require __DIR__.'/bootstrap.php';messenger_run(function($u){$expires=time()+300;$nonce=bin2hex(random_bytes(8));$payload=(int)$u['id'].'.'.$expires.'.'.$nonce;$secret=MessengerService::setting('messenger.realtime_secret');$signature=rtrim(strtr(base64_encode(hash_hmac('sha256',$payload,$secret,true)),'+/','-_'),'=');return ['token'=>rtrim(strtr(base64_encode($payload),'+/','-_'),'=').'.'.$signature,'expires_at'=>$expires,'realtime_url'=>MessengerService::setting('messenger.realtime_url')];});
